import React from "react";

import { List, ListItem, ListItemText, Typography, Paper } from "@mui/material";
import { useGangCity } from "./GangContext";

function FeedNarratif() {
  const { events } = useGangCity();
const bg = {
  anecdote:'#FEFEEE',
  secret:'#B8FFC8',
  evenement:'#FFC8C9'
}
  return (
    <Paper elevation={3} sx={{ maxHeight: '90vh', overflow: "auto", p: 2 }}>
      <Typography variant="h6" gutterBottom>
        Feed narratif
      </Typography>
      <List>
        {events
          .slice()
          .reverse()
          .map(event => (
            <ListItem key={event.id} alignItems="flex-start" sx={{background:bg[event.type]}}>
              <ListItemText
                primary={
                  <span>
                    <strong>{event.author} :</strong> {event.content}
                  </span>
                }
                secondary={event.type === "anecdote" ? "Anecdote" : event.type}
              />
            </ListItem>
          ))}
      </List>
    </Paper>
  );
}

export default FeedNarratif;
