import React, { useState, useEffect } from 'react';
import { Box } from '@mui/material';
import './dame.css';
import { Case } from './Case';

const Damier = () => {
  const taille = 10; // Nombre de cases par ligne et colonne
  const [cases, setCases] = useState([]);
  const [caseJouable, setCaseJouable] = useState(null);
  const [tourBlancs, setTourBlancs] = useState(true); // Variable pour suivre le tour des blancs
  const [pionSelectionne, setPionSelectionne] = useState(null); // Variable pour suivre le pion sélectionné par l'utilisateur

  // Fonction pour initialiser le tableau cases avec les pions blancs et noirs
  const initialiserCases = () => {
    const casesInitiales = Array.from({ length: taille }, () => Array(taille).fill(null));
/**
 * for debug
    casesInitiales[1][1]={ type: 'pion', couleur: 'black' }
    casesInitiales[1][3]={ type: 'pion', couleur: 'black' }
    casesInitiales[2][2]={ type: 'pion', couleur: 'white' }
    casesInitiales[7][7]={ type: 'pion', couleur: 'white' }
 */

    for (let x = 0; x < taille; x++) {
      for (let y = 0; y < taille; y++) {
        // Alterne les couleurs des cases pour créer un motif échiquier
        if ((x + y) % 2 === 0) {
          // Cases noires
          if (x < 4) {
            // 4 premières lignes : pions blancs
            casesInitiales[x][y] = { type: 'pion', couleur: 'black' };
          } else if (x >= taille - 4) {
            // 4 dernières lignes : pions noirs
            casesInitiales[x][y] = { type: 'pion', couleur: 'white' };
          }
        }
      }
    }
    setCases(casesInitiales);
  };

  useEffect(() => {
    initialiserCases();
  }, []);





  // Fonction pour gérer le clic sur une case
  const handleClickCase = (x, y) => {
    const pion = cases[x][y];

    if (pion !== null) {
      // Vérifie si le pion cliqué appartient au joueur en cours
      if ((tourBlancs && pion.couleur === 'white') || (!tourBlancs && pion.couleur === 'black')) {
        // Sélectionne le pion
        setPionSelectionne({ x, y });
      } else {
        // Désélectionne le pion si un autre pion ennemi est cliqué
        setPionSelectionne(null);
      }
    } else if (pionSelectionne !== null && caseJouable.length > 0) {
      // une case cliquable activee
      for(let cj=0;cj<caseJouable.length;cj++){
        if (caseJouable[cj].x === x && caseJouable[cj].y === y){
          deplacerPion(pionSelectionne.x, pionSelectionne.y, x, y);
          break;
        }
      }
   

    }
  };
  useEffect(() => {
    if (pionSelectionne == null)
      return;
    // allume les cases jouables
    const casesJouable = getCasesJouable(cases, pionSelectionne, tourBlancs);
    setCaseJouable(casesJouable);
  }, [pionSelectionne, tourBlancs]);

  
  // Fonction pour déplacer un pion vers une nouvelle position
  const deplacerPion = (xDepart, yDepart, xArrivee, yArrivee) => {
    // Vérifie si le déplacement est valide selon les règles de jeu
    // ...
    let tourSuivant = true;
    // Effectue le déplacement en mettant à jour le tableau cases
    const casesMisesAJour = JSON.parse(JSON.stringify(cases));
    casesMisesAJour[xArrivee][yArrivee] = cases[xDepart][yDepart];
    casesMisesAJour[xDepart][yDepart] = null;
    // prise ?
    if (Math.abs(xDepart - xArrivee) > 1) {
      // on enleve le pion entre
      const xPris = (xDepart < xArrivee) ? (xDepart + 1) : (xArrivee + 1);
      const yPris = (yDepart < yArrivee) ? (yDepart + 1) : (yArrivee + 1);
      casesMisesAJour[xPris][yPris] = null;

      // on verifie si une autre prise est possible, sinon on passe le tour
      const casesEncoreJouable = getCasesJouable(cases, { x: xArrivee, y: yArrivee }, tourBlancs);
      if (casesEncoreJouable.length > 0) {

      for(let cj=0;cj<casesEncoreJouable.length;cj++){
        if (Math.abs(casesEncoreJouable[cj].x - xArrivee) > 1){
             // une autre prise est possible
             tourSuivant = false;
             setCaseJouable(casesEncoreJouable);
             setPionSelectionne({ x: xArrivee, y: yArrivee });
          break;
        }
      }

      }
    }
    if((tourBlancs&&xArrivee===0) || (!tourBlancs&&xArrivee===(casesMisesAJour.length-1))){
      // au bout de la ligne, on fait une dame
      const pion = casesMisesAJour[xArrivee][yArrivee];
      casesMisesAJour[xArrivee][yArrivee] = {...pion, type:'dame'};
    }
    setCases(casesMisesAJour);
    if (tourSuivant) {

      // Passe au tour suivant (changement de joueur)
      setTourBlancs(!tourBlancs);
      setPionSelectionne(null); // Désélectionne le pion après le déplacement
      setCaseJouable(null);
    }
  };
  // au changement de tour
  useEffect(()=>{
    if(!tourBlancs)
      playAI({cases, callback:(bestMove)=>{
        // do the move for black

  const { from, to } = bestMove;
  deplacerPion(from.x,from.y, to.x, to.y);
      }})
  },[tourBlancs, cases])


  return (
    <Box
      className="boardDame"
      sx={{
        display: 'grid',
        gridTemplateColumns: `repeat(${taille}, 70px)`,
        gridTemplateRows: `repeat(${taille}, 70px)`,
      }}
    >
      {/* Affiche les cases du plateau avec les pions */}
      {cases.map((row, x) =>
        row.map((pion, y) => (
          <Case key={`${x}-${y}`}
            x={x} y={y} pion={pion}
            pionSelectionne={pionSelectionne}
            caseJouable={caseJouable}
            onClick={() => handleClickCase(x, y)} />

        ))
      )}
    </Box>
  );
};

export default Damier;



