// Fonction pour évaluer le plateau
const evaluateBoard = (cases) => {
  let score = 0;
  for (let i = 0; i < cases.length; i++) {
    for (let j = 0; j < cases[i].length; j++) {
      if ((i + j) % 2 === 0) {
      const pawn = cases[i][j];
      if (pawn !== null) {
        if (pawn.couleur === "black") {
          score += 1; // Ajouter 1 pour chaque pion noir
        } else {
          score -= 1; // Soustraire 1 pour chaque pion blanc
        }
      }
    }
    }
  }
  return score;
};


// Fonction pour faire jouer l'IA pour les noirs

  // Récupérer les pions noirs sur le plateau
  const collectPions = (cases, couleur)=>{
    const pawns = [];
    for (let x = 0; x < cases.length; x++) {
      for (let y = 0; y < cases[x].length; y++) {
        if (cases[x][y]?.couleur === couleur) {
          pawns.push({ x: x, y: y });
        }
      }
    }
    return pawns;
  }
  const playAI = (damier) => {
    const cases = JSON.parse(JSON.stringify(damier.cases));
  const blackPawns = collectPions(cases, "black");
  const whitePawns = collectPions(cases, "white");


  let bestMove;
  let bestScore = -Infinity;

  for (let i = 0; i < blackPawns.length; i++) {
    const pawn = blackPawns[i];
    const casesJouables = getCasesJouable(cases, pawn, false);

    for (let j = 0; j < casesJouables.length; j++) {
      const { x, y } = casesJouables[j];

      // Effectuer le mouvement
      const prevPawn = cases[x][y];
      cases[x][y] = cases[pawn.x][pawn.y];
      cases[pawn.x][pawn.y] = null;
      // prise eventuelle
      if(Math.abs(pawn.x-x)>1){
        const xPris = (pawn.x < x) ? (pawn.x + 1) : (x + 1);
        const yPris = (pawn.y < y) ? (pawn.y + 1) : (y + 1);
        cases[xPris][yPris] = null;
      }

      const score = minimax({cases, blackPawns, whitePawns, depth:3, maximizingPlayer:false}); // Recherche en profondeur de 2 niveaux

      // Annuler le mouvement
      cases[pawn.x][pawn.y] = cases[x][y];
      cases[x][y] = prevPawn;

      if (score > bestScore) {
        bestScore = score;
        bestMove = { from: { x: pawn.x, y: pawn.y }, to: { x, y } };
      }
    }
  }
  if(damier.callback)
    damier.callback(bestMove);
return bestMove;
  // Effectuer le meilleur mouvement trouvé
  // const { from, to } = bestMove;
  // cases[to.x][to.y] = cases[from.x][from.y];
  // cases[from.x][from.y] = null;
};
// Fonction pour minimax avec recherche en profondeur
const minimax = ({cases, depth, maximizingPlayer, blackPawns, whitePawns}) => {
  if (depth === 0) {
    return evaluateBoard(cases); // Évaluer le plateau à la profondeur actuelle
  }

  let bestScore = maximizingPlayer ? -Infinity : Infinity;
  const pawns = maximizingPlayer ? blackPawns : whitePawns;

  for (let i = 0; i < pawns.length; i++) {
    const pawn = pawns[i];
    const casesJouables = getCasesJouable(cases, pawn, maximizingPlayer);

    for (let j = 0; j < casesJouables.length; j++) {
      const { x, y } = casesJouables[j];

      // Effectuer le mouvement
      const prevPawn = cases[pawn.x][pawn.y];
      cases[x][y] = prevPawn;
      cases[pawn.x][pawn.y] = null;
       // prise eventuelle
       if(Math.abs(pawn.x-x)>1){
        const xPris = (pawn.x < x) ? (pawn.x + 1) : (x + 1);
        const yPris = (pawn.y < y) ? (pawn.y + 1) : (y + 1);
        cases[xPris][yPris] = null;
      }

      const score = minimax({cases, depth:depth - 1, maximizingPlayer:!maximizingPlayer, blackPawns, whitePawns});

      // Annuler le mouvement
      cases[pawn.x][pawn.y] = prevPawn;
      cases[x][y] = null;

      if (maximizingPlayer) {
        bestScore = Math.max(bestScore, score);
      } else {
        bestScore = Math.min(bestScore, score);
      }
    }
  }

  return bestScore;
};



const getCasesJouable = (cases, forPion, isBlanc) => {
  const jouables = [];
  const direction = isBlanc ? -1 : 1;

  const isCellFree = (x, y) => {
    if (x >= 0 && x < cases.length && y >= 0 && y < cases.length) {
      return cases[x][y] == null;
    }
    return false;
  };
  
  const isEnemyPawn = (x, y, isBlanc) => {
    if (x >= 0 && x < cases.length && y >= 0 && y < cases.length) {
      const nextPion = cases[x][y];
      return nextPion !== null && ((isBlanc && nextPion.couleur ==='black') || (!isBlanc &&  nextPion.couleur==='white'));    }
    return false;
  };
  // Vérification pour x-1 et y+/- 1
  if (isCellFree(forPion.x + direction, forPion.y - 1)) {
    jouables.push({ x: forPion.x + direction, y: forPion.y - 1 });
  }
  if (isCellFree(forPion.x + direction, forPion.y + 1)) {
    jouables.push({ x: forPion.x + direction, y: forPion.y + 1 });
  }

  // Vérification pour le saut par-dessus le pion ennemi
  if (isEnemyPawn(forPion.x + direction, forPion.y - 1,isBlanc) && isCellFree(forPion.x + direction * 2, forPion.y - 2)) {
    jouables.push({ x: forPion.x + direction * 2, y: forPion.y - 2 });
  }
  if (isEnemyPawn(forPion.x + direction, forPion.y + 1, isBlanc) && isCellFree(forPion.x + direction * 2, forPion.y + 2)) {
    jouables.push({ x: forPion.x + direction * 2, y: forPion.y + 2 });
  }
  // saut possible en arriere
  if (isEnemyPawn(forPion.x - direction, forPion.y - 1, isBlanc) && isCellFree(forPion.x - direction * 2, forPion.y - 2)) {
    jouables.push({ x: forPion.x - direction * 2, y: forPion.y - 2 });
  }
    if (isEnemyPawn(forPion.x - direction, forPion.y + 1, isBlanc) && isCellFree(forPion.x - direction * 2, forPion.y + 2)) {
      jouables.push({ x: forPion.x - direction * 2, y: forPion.y + 2 });
  }

  return jouables;
};

