import React, { useState } from "react";
import { Box, AppBar, Toolbar, Typography, Grid, Paper, CssBaseline, List, ListItem, ListItemButton, ListItemAvatar, Avatar, ListItemText, ListItemSecondaryAction, Button, Chip, Stack, Divider, Tooltip } from "@mui/material";
import { GangCityProvider, useGangCity } from "./GangContext";
import FeedNarratif from "./FeedNarratif";
import CityMap from "./cityMap";
import { GANG_ACTIONS } from "./GangData";
import { Visibility, Bolt, Celebration, EmojiEvents, Security, ElectricBolt } from "@mui/icons-material";
import { DistrictChoiceDialog, MoreMenu } from "./GangDialogs";
import CityMapBlobs from "./cityMap";

const GangCity = () => {
  return <>
    <CssBaseline />
    <Box sx={{ width: '100%', height: '100%', overflow: 'auto' }}>
      <GangCityProvider>
        <GangBoard />
      </GangCityProvider>
    </Box>
  </>
}

export default GangCity;

const GangBoard = () => {
  const { districts, setDistricts, playerDistrictId, setPlayerDistrictId, utilFunc, endPlayerTurn, currentTurnIndex } = useGangCity();
  const userDistrict = React.useMemo(() => {
    return districts.find(d => d.id === playerDistrictId);
  }, [districts, playerDistrictId]);

  const [anchorEl, setAnchorEl] = useState(null);
  const onMenuAction = action => {
    //TODO
    if (action === 'changerQuartier')
      setPlayerDistrictId(null);
  }
  const onActionCity = (action, otherDistrict) => {

    // Sinon => action sur targetDistrict
    const log = action.effect(userDistrict, otherDistrict, utilFunc);
    if (log != null)
      utilFunc.showAlert(log);
    userDistrict.actionPoint-=action.cost;
    setDistricts(prevDistricts => {
      return prevDistricts.map(dist => {
        if (dist.id === userDistrict.id) {
          return userDistrict;
        }
        else if (otherDistrict!=null && dist.id === otherDistrict.id){
            return otherDistrict;
        }
        return dist;
      })
    });
  }

  const handleMenu = (event) => setAnchorEl(event.currentTarget);
  const handleClose = () => setAnchorEl(null);
  return <>
    <AppBar position="static">
      <Toolbar sx={{ display: 'flex', justifyContent: 'space-between', gap: 3 }}>
        <Typography variant="h6" component="div">
          GangCity
        </Typography>
        <Typography variant="h6" component="div">
          {userDistrict?.name} for ever !
        </Typography>
        <Typography variant="subtitle1" component="div">
          a {districts[currentTurnIndex]?.name} de jouer
        </Typography>
        <Box sx={{ display: 'flex' }}>
          <Button variant="contained" color="secondary" onClick={endPlayerTurn}>Fin du tour</Button>
          <MoreMenu anchorEl={anchorEl} handleClose={handleClose} handleMenu={handleMenu}
            moreAction={onMenuAction} />
        </Box>

      </Toolbar>
    </AppBar>
    {playerDistrictId == null ?
      <Paper elevation={2} sx={{ margin: 'auto', width: '50%' }}>
        <Typography variant="h5">Choisissez votre quartier</Typography>
        <List>
          {districts.map((district) => (
            <ListItem key={district.id} disablePadding>
              <ListItemButton onClick={() => setPlayerDistrictId(district.id)}>
                <ListItemAvatar>
                  <Avatar sx={{ bgcolor: "#fff", color: "#1976d2", fontWeight: "bold" }}>
                    {district.name[0]}
                  </Avatar>
                </ListItemAvatar>
                <ListItemText
                  primary={district.name}
                  secondary={
                    <Box>
                      <Typography component="span" variant="caption">
                        Pop: {district.population} | Mood: {district.mood} | Eco: {district.santeEconomique}
                      </Typography>
                    </Box>
                  }
                />
              </ListItemButton>
            </ListItem>
          ))}
        </List>
      </Paper>
      :
      <Box sx={{ flexGrow: 1, p: 2 }}>
        <Grid container spacing={2}>
          {/* Carte des quartiers */}
          <Grid item xs={12} md={7}>
            <Paper elevation={3} sx={{ height: "70vh", p: 2, overflow: "auto" }}>
              {/* Ici tu mettras la carte stylisée des quartiers */}
              <Typography variant="h5" gutterBottom>
                Carte des Quartiers
              </Typography>
              <CityMapBlobs onAction={onActionCity} />
              {Array.from({ length: userDistrict.actionPoint }).map((_, index) => (
                <ElectricBolt key={index} sx={{ color: '#cAcA48' }} />
              ))}
            </Paper>
          </Grid>

          {/* Feed narratif et panneau d'influence */}
          <Grid item xs={12} md={5}>
            <FeedNarratif />

          </Grid>

        </Grid>
      </Box>
    }
    <Box component="footer" sx={{ p: 2, textAlign: "center", bgcolor: "background.paper" }}>
      <Typography variant="body2" color="text.secondary">
        DPY © 2025
      </Typography>
    </Box>
  </>
}
