import React, { useCallback } from 'react';
import { Box } from '@mui/material';
import { Pion } from './Pion';

export const Case = ({ pion, x, y, pionSelectionne, caseJouable, ...props }) => {

  const isJouable = useCallback((x, y) => {
    if (caseJouable == null)
      return false;
    let isok = false;
    caseJouable.forEach(c => {
      if (c.x === x && c.y === y)
        isok = true;
    });
    return isok;
  }, [caseJouable]);
  const pionSelected = pionSelectionne != null && pionSelectionne.x == x && pionSelectionne.y === y;

  const czjouable = isJouable(x, y);
  const pionJouable = pionSelected && caseJouable != null && caseJouable.length > 0;
  return <Box

    className={`${x % 2 === y % 2 ? 'black' : 'white'}`}
    {...props}
    sx={{
      width: '70px',
      height: '70px',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      fontSize: '24px',
      opacity: czjouable ? 0.4 : 1
    }}
  >
    <Pion pion={pion}
      jouable={pionJouable}
      selected={pionSelected} />

  </Box>;
};
