import React, { useState } from "react";
import { Popover, MenuItem, Typography, Box } from "@mui/material";
import { useGangCity } from "./GangContext";
import { GANG_ACTIONS } from "./GangData";
import { QuartierDialog } from "./GangDialogs";
import { getQuartierIcons } from "./GangUtils";

// Couleurs pour moods et relations
const moodColors = {
  joyeux: "#4caf50",
  fêtard: "#ff9800",
  tendu: "#f44336",
  rebelle: "#9c27b0",
  studieux: "#2196f3",
  neutre: "#bdbdbd"
};
const relationColors = {
  alliance: "#4caf50",
  guerre: "#f44336"
};

// Génère une forme patatoïde (ellipse déformée)
function getBlobPath(cx, cy, r, variance = 0.2) {
  const points = [];
  for (let i = 0; i < 8; i++) {
    const angle = (Math.PI * 2 * i) / 8;
    const rad = r * (1 + (Math.random() - 0.5) * variance);
    points.push([
      cx + Math.cos(angle) * rad,
      cy + Math.sin(angle) * rad
    ]);
  }
  let d = `M${points[0][0]},${points[0][1]}`;
  for (let i = 1; i < points.length; i++) {
    d += ` Q${cx},${cy} ${points[i][0]},${points[i][1]}`;
  }
  d += ` Q${cx},${cy} ${points[0][0]},${points[0][1]} Z`;
  return d;
}

const MAPWIDTH=650;
const MAPHEIGHT=400;

const districtPositions = {
  nord:      { cx: MAPWIDTH/2, cy: 70 },
  central:    { cx: MAPWIDTH/2-50, cy: MAPHEIGHT/2 },
  sud:       { cx: MAPWIDTH/2, cy: MAPHEIGHT-60 },
  est:       { cx: MAPWIDTH-100, cy: MAPHEIGHT/2 },
  techno:{ cx: 100, cy: MAPHEIGHT/2-50 },
  vieuxport: { cx: 150, cy: MAPHEIGHT/2+50 }
  // Ajoute d'autres quartiers ici selon ta carte
};

const CityMapBlobs = ({ onAction }) => {
  const { districts, playerDistrictId } = useGangCity();
const userDistrict = districts.find(d => d.id === playerDistrictId);
  const [selectedDistrict, setSelectedDistrict] = useState(null);
const [dialogOpen, setDialogOpen] = React.useState(false);

  // Placement des quartiers sur un cercle
  const maxPop = Math.max(...districts.map(d => d.population));
  const minBlob = 40, maxBlob = 90;

  // Calcul des positions pour chaque quartier
 const positions = districts.map(district => {
  const pos = districtPositions[district.id] || { cx: MAPWIDTH/2, cy: MAPHEIGHT/2 }; // fallback au centre
  return { id: district.id, ...pos };
});
  const getPosition = (id) => positions.find(p => p.id === id);

const handleDistrictClick = (district) => {
  setSelectedDistrict(district);
  setDialogOpen(true);
};

  return (
    <Box sx={{ width: MAPWIDTH, height: MAPHEIGHT, position: "relative" }}>
      <svg width={MAPWIDTH} height={MAPHEIGHT} style={{ background: "#e3e3e3", borderRadius: 16 }}>
       
        {/* Quartiers patatoïdes */}
        {districts.map((district, i) => {
          const pos = positions[i];
          const r = minBlob + (maxBlob - minBlob) * (district.population / maxPop);
          const color = moodColors[district.mood] || "#90caf9";
          const path = getBlobPath(pos.cx, pos.cy, r, 0.22);

          return (
            <g key={district.id}>
              <path
                d={path}
                fill={color}
                stroke="#222"
                strokeWidth={district.id === playerDistrictId ? 4 : 2}
                style={{ cursor: "pointer", transition: "fill 0.2s" }}
                onClick={e => handleDistrictClick(district)}
                onMouseOver={e => e.target.setAttribute("fill", "#ffe082")}
                onMouseOut={e => e.target.setAttribute("fill", color)}
              />
              <text
                x={pos.cx}
                y={pos.cy}
                textAnchor="middle"
                alignmentBaseline="middle"
                fontWeight="bold"
                fontSize={18}
                fill="#222"
                pointerEvents="none"
              >
                {district.name}
              </text>
              <text
                x={pos.cx}
                y={pos.cy + 22}
                textAnchor="middle"
                alignmentBaseline="middle"
                fontSize={12}
                fill="#333"
                pointerEvents="none"
              >
                {district.population} hab.
              </text>
              <VisualIndicators
                reputation={district.reputation}
                santeEconomique={district.santeEconomique}
                x={pos.cx+40}
                y={pos.cy + r} // positionne juste au-dessus du blob
              />
            </g>
          );
        })}
         {/* Lignes pour alliances et guerres */}
        {districts.map((district) =>
  Object.entries(district.links).map(([otherId, relation]) => {
    if (relation !== "alliance" && relation !== "guerre") return null;
    if (district.id > otherId) return null; // éviter doublons
    const posA = getPosition(district.id);
    const posB = getPosition(otherId);
    if (!posA || !posB) return null;

    // Couleurs
    const color = relation === "alliance" ? "#4caf50" : "#f44336";
    const dash = relation === "alliance" ? "6 4" : undefined;
    const width = relation === "guerre" ? 5 : 3;

    return (
      <g key={`${district.id}-${otherId}`}>
        {/* Ligne de fond (contour noir/blanc, plus épais, semi-transparent) */}
        <line
          x1={posA.cx}
          y1={posA.cy}
          x2={posB.cx}
          y2={posB.cy}
          stroke="#000"
          strokeWidth={width + 4}
          strokeOpacity={0.45}
          strokeLinecap="round"
        />
        {/* Ligne principale colorée */}
        <line
          x1={posA.cx}
          y1={posA.cy}
          x2={posB.cx}
          y2={posB.cy}
          stroke={color}
          strokeWidth={width}
          strokeDasharray={dash}
          strokeLinecap="round"
        />
      </g>
    );
  })
)}


      </svg>
<QuartierDialog   open={dialogOpen}
  district={selectedDistrict}
  isPlayer={selectedDistrict?.id === playerDistrictId}
  actionPoint={userDistrict.actionPoint}
  actions={GANG_ACTIONS}
  onAction={(action, targetDistrict) => {
    // Exécute l'action ici
    onAction(action, targetDistrict);
    setDialogOpen(false);
  }}
  onClose={() => setDialogOpen(false)}/>
     
    </Box>
  );
};

export default CityMapBlobs;


const VisualIndicators = ({ reputation, santeEconomique, x, y }) => {
  const starGreen = '⭐';   // pour réputation positive
  const starRed = '💩';     // pour réputation négative (remplace par une étoile rouge SVG si tu veux)
  const coinRed = '🥕';   // pour santé économique neg
  const coinGreen = '💰';     // pour santé économique pos

  const reputationIcons = getQuartierIcons(reputation, starGreen, starRed);
  const santeIcons = getQuartierIcons(santeEconomique, coinGreen, coinRed);

  return (
    <g>
      {/* Étoiles pour la réputation, empilées verticalement */}
      {reputationIcons.map((icon, idx) => (
        <text
          key={`rep-${idx}`}
          x={x}
          y={y - 24 - idx * 14}
          fontSize={14}
          textAnchor="middle"
        >
          {icon}
        </text>
      ))}
      {/* Pièces pour la santé économique, à droite des étoiles */}
      {santeIcons.map((icon, idx) => (
        <text
          key={`eco-${idx}`}
          x={x + 16}
          y={y - 24 - idx * 14}
          fontSize={14}
          textAnchor="middle"
        >
          {icon}
        </text>
      ))}
    </g>
  );
};

