import React, { useEffect, useState } from 'react';

import { styled } from '@mui/system';
import moleImg from '../fourmis/images/puceronInactif.png';
import coupVide from './images/coupVide.mp3';
import coupReussi from './images/coupReussi.mp3';
import { soundManager } from '../rpg/sons/SoundManager';

import {
  Box,
  Button,
  Typography,
  Grid,
  Paper,
  Stack,
} from '@mui/material';
import { GameOver } from '../ChuckNorrisFact';


// === CONFIG ===
const GRID_SIZE = 9;
const GAME_DURATION = 20000; // ms

// === STYLED COMPONENTS ===
const Hole = styled(Paper)(({ isMole }) => ({
  width: '100%',
  paddingTop: '100%',
  position: 'relative',
  backgroundColor: isMole ? '#795548' : '#ccc',
  cursor: 'pointer',
  transition: 'background-color 0.2s ease',
  overflow: 'hidden',
}));

const MoleImg = styled('img')(({ isFading }) => ({
  position: 'absolute',
  top: '15%',
  left: '15%',
  width: '70%',
  height: '70%',
  pointerEvents: 'none',
  opacity: isFading ? 0 : 1,
  transition: 'opacity 0.3s ease-out',
}));

// === MAIN COMPONENT ===
const WhackAMole = ({onFinish}) => {
  const [moleIndex, setMoleIndex] = useState(null);
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(GAME_DURATION / 1000);
  const [gameRunning, setGameRunning] = useState(false);
  const [moleShowTime, setMoleShowTime] = useState(800);
  const [isFading, setIsFading] = useState(false);

  useEffect(() => {
    soundManager.loadSounds({coupReussi, coupVide})
  },[]);

  const startGame = (difficultyTime) => {
    setScore(0);
    setTimeLeft(GAME_DURATION / 1000);
    setGameRunning(true);
    setMoleShowTime(difficultyTime);
  };

  // Timer countdown
  useEffect(() => {
    if (!gameRunning) return;

    const interval = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          clearInterval(interval);
          setGameRunning(false);
          setGameOver(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [gameRunning]);

  // Mole interval
  useEffect(() => {
    if (!gameRunning) {
      setMoleIndex(null);
        if(score>0 && typeof onFinish==='function') 
            onFinish(score);
      return;
    }

    const moleInterval = setInterval(() => {
      setTimeout(() => {
        setIsFading(true);
      }, 300); // start fade-out just before switch

      const randomIndex = Math.floor(Math.random() * GRID_SIZE);
      setMoleIndex(randomIndex);
      setIsFading(false);
    }, moleShowTime);

    return () => clearInterval(moleInterval);
  }, [gameRunning, moleShowTime]);
const [isGameOver, setGameOver]=useState(false);
  const handleClick = (index) => {
    if (index === moleIndex) {
      const scorByHit=moleShowTime==750?1:2;//1 en facile, 2 en difficile
      setScore(prev => prev + scorByHit);
        soundManager.play('coupReussi');
      setMoleIndex(null);
      setIsFading(false);
    }
    else
        soundManager.play('coupVide');
  };

  return (
    <Box sx={{ maxWidth: 400, display:'flex',margin: '20px', alignitems:'end'
      ,gap:'10px', padding: 2,color:'black' }}>
       <GameOver open={isGameOver} score={score}  
              gameName="WhackAMole"
                  handleClose={()=>setGameOver(false) } />
        <Box>

      <Typography variant="h4" align="center" gutterBottom>
        Whack-a-Mole 🐹
      </Typography>

      <Box display="flex" justifyContent="space-between" mb={2}>
        <Typography variant="h6">Score: {score}</Typography>
        <Typography variant="h6">Temps: {timeLeft}s</Typography>
      </Box>

      <Box textAlign="center" mt={3}>
        <Stack spacing={1} direction="row" justifyContent="center">
          <Button
            variant="contained"
            color="success"
            onClick={() => startGame(750)}
            disabled={gameRunning}
          >
            Mode Facile 😌
          </Button>
          <Button
            variant="contained"
            color="error"
            onClick={() => startGame(600)}
            disabled={gameRunning}
          >
            Mode Difficile 😈
          </Button>
        </Stack>
      </Box>
        </Box>


      <Grid container spacing={1}>
        {[...Array(GRID_SIZE)].map((_, index) => (
          <Grid item xs={4} key={index}>
            <Hole
              isMole={index === moleIndex}
              onClick={() => handleClick(index)}
              elevation={3}
            >
              {index === moleIndex && (
                <MoleImg
                  src={moleImg}
                  alt="Mole"
                  isFading={isFading}
                />
              )}
            </Hole>
          </Grid>
        ))}
      </Grid>

    </Box>
  );
};

export default WhackAMole;
