// Deck.js
import React from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';

import { Card, CardContent, Typography } from "@mui/material";
import { faCannabis, faClover, faDiamond, faHeart, faSpa } from '@fortawesome/free-solid-svg-icons';
import { makeStyles } from '@mui/styles';
import dos from './dosDeCarte.png';


const ranks = [{name:'2', value:2},
{name:'3', value:3},
{name:'4', value:4},
{name:'5', value:5},
{name:'6', value:6},
{name:'7', value:7},
{name:'8', value:8},
{name:'9', value:9},
{name:'10', value:10},
{name:'V', value:11, label:"Valet"},
{name:'D', value:12, label:"Dame"},
{name:'R', value:13,label:"Roi"},
{name:'A', value:14, label:"As"}];
export const suits = ['pique', 'coeur', 'carreau', 'trèfle'];
export const carteNameByValue = value=>{
  let name='Inconnue';
  ranks.forEach(c=>{
    if(c.value===Number(value))
      name=c.label||c.name;
  })
  return name;
}
export const createDeck = () => {
  const deck = [];

  for (let suit of suits) {
    for (let rank of ranks) {
      deck.push({ rank, suit });
    }
  }

  return shuffle(deck);
};

export const shuffle = (deck) => {
    for (let i = deck.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [deck[i], deck[j]] = [deck[j], deck[i]];
    }
  
    return deck;
  };

  export const useCardStyles = makeStyles((theme) => ({
    carteContainer: {
        display:'flex',flexDirection:'row',
      position: 'relative',
      marginLeft: theme.spacing(2), // Espacement entre les cartes
    },
    alertStyle:{
      zIndex:2,
      position:'relative'
    },
    joueurCardRoot: {
      background: 'linear-gradient(45deg, #ffd700, #ffaf00)', // Dégradé doré en diagonale
      padding: '12px', // Espacement intérieur du header
    },
  }));

  export const Carte = ({ card, carte2=false, retourne=false }) => {
    const classes = useCardStyles();
    const iconColor = card.suit === 'coeur' || card.suit === 'carreau' ? 'red' : 'black';
    const cardSX = {
        position: 'relative',
      zIndex: 1,
      minWidth:80,
      minHeight:110,
      marginBottom:'-32px'
    }
    if(carte2){
        // donne un effet de rotation
        cardSX.left='-30px';
        cardSX.top='5px';
        cardSX.rotate='10deg';
    }
    
    return (
        <Card variant="outlined" sx={cardSX}> 
          <CardContent sx={{paddingTop:'5px', paddingLeft:'5px',textAlign:'start', background:retourne?`url(${dos})`:'#f7f7d9', backgroundSize:'cover', height:'100px'}}>
            {!retourne&&<Typography variant="h6">{card.rank.name}
            {card.suit === 'pique' && <FontAwesomeIcon icon={faSpa} style={{ color: iconColor }} />}
            {card.suit === 'coeur' && <FontAwesomeIcon icon={faHeart} style={{ color: iconColor }} />}
            {card.suit === 'carreau' && <FontAwesomeIcon icon={faDiamond} style={{ color: iconColor }} />}
            {card.suit === 'trèfle' && <FontAwesomeIcon icon={faClover} style={{ color: iconColor }} />}
            </Typography>}
          </CardContent>
        </Card>
      );
    };
    