import React from 'react';
import { Circle } from '@mui/icons-material';


export const Pion = ({ pion, selected = false, jouable = false }) => {

  if (pion == null)
    return null;
  const pionStyle = { fontSize: '40px', fill: pion.couleur };
  if (selected)
    pionStyle.border = '5px solid ' + (jouable ? 'limegreen' : 'red');

  else
    pionStyle.border = '2px solid ' + (pion.couleur === 'white' ? 'black' : 'white');
//TODO le style pour pion.type==='dame' !!
  return <Circle className={`piece ${pion.couleur}`} sx={pionStyle} />;
};
