import React, { useEffect } from 'react';
import { KeyboardDoubleArrowLeft, KeyboardDoubleArrowRight, KeyboardDoubleArrowUp, KeyboardDoubleArrowDown, ArrowBack } from '@mui/icons-material';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import { Card, CardActions, CardContent, CardHeader, CardMedia, Typography } from '@mui/material';
import { useGlobalScores } from "../App";

const GameOver = ({ open=false,gameName, score, handleClose, handleRestart }) =>{
  const {setScore, getScoreByGame} = useGlobalScores();
  const [hiScore, setHiScore] = React.useState('Aucun');
  const doClose =(evt,reason)=>{
    if(reason!='backdropClick')
     handleClose(evt);
  } 
  const doRestart=(evt)=>{
    handleRestart();
    handleClose(evt);
  }
  useEffect(()=>{
    if(gameName!=null){
      const hiscores = getScoreByGame(gameName);
      if(hiscores!=null && hiscores.score!=null)
        setHiScore(hiscores.score);
      if(hiscores.score<score)
        setScore(gameName,score);
    }
  },[gameName, score]);
  return (
    <Dialog open={open} onClose={doClose}>
      <DialogTitle>Partie terminée</DialogTitle>
      <DialogContent>
        <Typography color="primary">Votre score : {score}</Typography>
        <Typography variant="caption" color="text.secondary">Hi-score actuel: {hiScore}</Typography>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose}>Fermer</Button>
        <Button onClick={doRestart}>Recommencer</Button>
      </DialogActions>
    </Dialog>
  );
}

export const Score2048 = ({handleRestart, lastSwipe, score, gridSize, setGridSize})=>{

    const getArrowImage = dir=>{
      let icon=ArrowBack;
        switch(dir){
            case 'left':
              return KeyboardDoubleArrowLeft
                case 'right':
                  return KeyboardDoubleArrowRight
                    case 'up':
                      return KeyboardDoubleArrowUp
                        case 'down':
                          return KeyboardDoubleArrowDown
                            default:break
        }
        return icon;
    }
    const FlecheIcon = getArrowImage(lastSwipe);
    return <Card sx={{ maxWidth: 345 }}>
    <CardHeader
      title="2048"
      subheader={`Score : ${score}`}
    />
    <CardContent>
      <div>
       {<FlecheIcon color="primary" />}
      </div>
    </CardContent>
    <CardActions>
      <div style={{display:"flex"}}>

      <Button size="small" variant="contained" sx={{minWidth:10}} color={gridSize==3?'secondary':'primary'} 
        onClick={()=>{setGridSize(3)}}>3</Button>
        <Button size="small" variant="contained" sx={{minWidth:10}} color={gridSize==4?'secondary':'primary'} 
          onClick={()=>{setGridSize(4)}}>4</Button>
          <Button size="small"  variant="contained" sx={{minWidth:10}} color={gridSize==6?'secondary':'primary'} 
            onClick={()=>{setGridSize(6)}}>6</Button>
            <Button size="small"  variant="contained" sx={{minWidth:10}} color={gridSize==12?'secondary':'primary'} 
              onClick={()=>{setGridSize(12)}}>12</Button>
      </div>
      <Button size="small" onClick={handleRestart}>Recommencer</Button>
    </CardActions>
  </Card>
}

export default GameOver;